    " * ones so that full white stays full wh"
    "ite instead of landing at 248. */\n  cons"
    "t img = pctx.createImageData(w, h);\n  co"
    "nst d = img.data;\n  for (let i = 0, j = "
    "0; i < n; i++) {\n    const c = px[i];\n  "
    "  const r = (c >> 11) & 31, g = (c >> 5)"
    " & 63, b = c & 31;\n    d[j++] = (r << 3)"
    " | (r >> 2);\n    d[j++] = (g << 2) | (g "
    ">> 4);\n    d[j++] = (b << 3) | (b >> 2);"
    "\n    d[j++] = 255;\n  }\n  pctx.putImageDa"
    "ta(img, x, y);\n  showPixels();\n}\n\n/* ---"
    "- the connection -----------------------"
    "---------------------------- */\n\nfunctio"
    "n connect() {\n  const url = (location.pr"
    "otocol === \"https:\" ? \"wss://\" : \"ws://\""
    ") +\n              location.host + \"/ws\";"
    "\n  const ws = new WebSocket(url);\n  ws.b"
    "inaryType = \"arraybuffer\";\n  st.ws = ws;"
    "\n\n  ws.onopen = () => {\n    ui.dot.class"
    "List.add(\"on\");\n    ui.note.textContent "
    "= location.host;\n    ws.send(new Uint8Ar"
    "ray([IN_HELLO]));\n  };\n  ws.onclose = (e"
    "v) => {\n    ui.dot.classList.remove(\"on\""
    ");\n    /*\n     * The board allows one cl"
    "ient: there is one screen and one keyboa"
    "rd.  When\n     * a second browser takes "
    "the link it says so in the close, and th"
    "e one that\n     * lost it must NOT come "
    "straight back - two pages reconnecting a"
    "t each\n     * other is a link that flaps"
    " about once a second and looks like a fa"
    "ult.\n     * Wait to be asked instead.\n  "
    "   */\n    if (ev && ev.reason === \"repla"
    "ced\") {\n      ui.note.textContent = \"ano"
    "ther device has the screen \342\200\224 tap to ta"
    "ke it\";\n      ui.splash.textContent =\n  "
    "      \"Another browser is connected to t"
    "his board.\\n\" +\n        \"Tap anywhere to"
    " take the screen back.\";\n      ui.splash"
    ".hidden = false;\n      const take = () ="
    "> {\n        document.removeEventListener"
    "(\"pointerdown\", take);\n        ui.splash"
    ".hidden = true;\n        connect();\n     "
    " };\n      document.addEventListener(\"poi"
    "nterdown\", take);\n      return;\n    }\n  "
    "  ui.note.textContent = \"reconnecting\342\200\246"
    "\";\n    /*\n     * A second, not immediate"
    "ly.  A board that has just been reset re"
    "fuses\n     * connections for a few secon"
    "ds, and a page that retries as fast as i"
    "t can\n     * is a page that spends that "
    "time producing errors.\n     */\n    setTi"
    "meout(connect, 1000);\n  };\n  ws.onerror "
    "= () => ws.close();\n  ws.onmessage = (ev"
    ") => onMessage(new DataView(ev.data));\n}"
    "\n\nfunction onMessage(v) {\n  if (v.byteLe"
    "ngth < 1) return;\n  const op = v.getUint"
    "8(0);\n\n  if (op === OP_INFO) {\n    st.su"
    "rfW = v.getUint16(1, true);\n    st.surfH"
    " = v.getUint16(3, true);\n    const cols "
    "= v.getUint8(5), rows = v.getUint8(6);\n "
    "   st.cellW = v.getUint8(7) || 8;\n    st"
    ".cellH = v.getUint8(8) || 16;\n    if (co"
    "ls && rows && (cols !== st.cols || rows "
    "!== st.rows)) {\n      st.cols = cols; st"
    ".rows = rows; resizeText();\n    }\n    if"
    " (st.surfW && st.surfH) resizePix(st.sur"
    "fW, st.surfH);\n    return;\n  }\n\n  if (op"
    " === OP_ROW) {\n    const y = v.getUint8("
    "1), n = v.getUint8(2);\n    if (y >= st.r"
    "ows) return;\n    for (let x = 0; x < n &"
    "& x < st.cols; x++) {\n      st.cells[y *"
    " st.cols + x] =\n        v.getUint8(3 + x"
    " * 2) | (v.getUint8(4 + x * 2) << 8);\n  "
    "  }\n    schedulePaint([y]);\n    showText"
    "();\n    return;\n  }\n\n  if (op === OP_CUR"
    "SOR) {\n    const x = v.getUint8(1), y = "
    "v.getUint8(2);\n    const ch = v.getUint8"
    "(3), attr = v.getUint8(4), on = v.getUin"
    "t8(5) !== 0;\n    const was = { x: st.cur"
    ".x, y: st.cur.y };\n    if (y < st.rows &"
    "& x < st.cols) st.cells[y * st.cols + x]"
    " = ch | (attr << 8);\n    st.cur = { x, y"
    ", on };\n    schedulePaint([was.y, y]);\n "
    "   showText();\n    return;\n  }\n\n  if (op"
    " === OP_RAW || op === OP_PACK || op === "
    "OP_IDX) {\n    band(op, v, 1, v.byteLengt"
    "h);\n  }\n}\n\nfunction send(bytes) {\n  if ("
    "st.ws && st.ws.readyState === 1) st.ws.s"
    "end(new Uint8Array(bytes));\n}\n\n/* ---- k"
    "eys ------------------------------------"
    "------------------------- */\n\nfunction s"
    "endKey(kind, hid, unicode, mods) {\n  con"
    "st m = (mods === undefined ? st.sticky :"
    " mods);\n  send([IN_KEY, kind, m, hid & 2"
    "55, hid >> 8, unicode & 255,\n        (un"
    "icode >> 8) & 255, 0]);\n}\n\nfunction tap("
    "hid) {\n  sendKey(1, hid, 0);\n  sendKey(2"
    ", hid, 0);\n  clearSticky();\n}\n\nfunction "
    "clearSticky() {\n  if (!st.sticky) return"
    ";\n  st.sticky = 0;\n  for (const b of ui."
    "keys.querySelectorAll(\"button.held\")) {\n"
    "    b.classList.remove(\"held\");\n  }\n}\n\n/"
    "*\n * The bar of keys a phone's own keybo"
    "ard does not have.\n *\n * Ctrl and Alt la"
    "tch rather than repeat: there is no way "
    "to hold one down and\n * press a letter o"
    "n a touch screen, so a tap arms it for t"
    "he next keystroke and\n * the keystroke c"
    "lears it.  That is how every terminal ap"
    "plication on a phone\n * has to do it, an"
    "d it is the reason Ctrl+C from here reac"
    "hes the shell at all.\n */\nconst KEYBAR ="
    " [\n  [\"Esc\", () => tap(K.esc)],\n  [\"Tab\""
    ", () => tap(K.tab)],\n  [\"Ctrl\", \"mod\", M"
    "OD.ctrl],\n  [\"Alt\", \"mod\", MOD.alt],\n  ["
    "\"\342\206\221\", () => tap(K.up)],\n  [\"\342\206\223\", () =>"
    " tap(K.down)],\n  [\"\342\206\220\", () => tap(K.lef"
    "t)],\n  [\"\342\206\222\", () => tap(K.right)],\n  [\""
    "\342\217\216\", () => tap(K.enter)],\n  [\"\342\214\253\", () "
    "=> tap(K.back)],\n  [\"Home\", () => tap(K."
    "home)],\n  [\"End\", () => tap(K.end)],\n  ["
    "\"PgUp\", () => tap(K.pgup)],\n  [\"PgDn\", ("
    ") => tap(K.pgdn)],\n  [\"Del\", () => tap(K"
    ".del)],\n  [\"F1\", () => tap(K.f1)], [\"F2\""
    ", () => tap(K.f2)], [\"F3\", () => tap(K.f"
    "3)],\n  [\"F4\", () => tap(K.f4)], [\"F5\", ("
    ") => tap(K.f5)], [\"F6\", () => tap(K.f6)]"
    ",\n  [\"F7\", () => tap(K.f7)], [\"F8\", () ="
    "> tap(K.f8)], [\"F9\", () => tap(K.f9)],\n "
    " [\"F10\", () => tap(K.f10)], [\"F11\", () ="
    "> tap(K.f11)], [\"F12\", () => tap(K.f12)]"
    ",\n];\n\nfor (const item of KEYBAR) {\n  con"
    "st b = document.createElement(\"button\");"
    "\n  b.textContent = item[0];\n  if (item[1"
    "] === \"mod\") {\n    const bit = item[2];\n"
    "    b.onclick = () => {\n      st.sticky "
    "^= bit;\n      b.classList.toggle(\"held\","
    " (st.sticky & bit) !== 0);\n    };\n  } el"
    "se {\n    b.onclick = item[1];\n  }\n  ui.k"
    "eys.appendChild(b);\n}\n\n/* ---- the keybo"
    "ard the page carries itself ------------"
    "------------------ */\n\n/*\n * Drawn here "
    "rather than asked of the phone, because "
    "the phone says no.\n *\n * A browser raise"
    "s its keyboard for a field the person ca"
    "n see and refuses it\n * for one parked o"
    "ff screen at zero opacity - and off scre"
    "en is the only place\n * such a field can"
    " be parked behind a full-screen canvas. "
    " Reported as \"the\n * keyboard is not the"
    "re, only the one row with Esc and Tab\", "
    "and it was exactly\n * that.  So these ke"
    "ys are the page's own, and whether they "
    "appear is not an\n * opinion anything els"
    "e gets to have.  `abc` in the header sti"
    "ll tries the\n * phone's, for whoever wan"
    "ts their own autocomplete and emoji.\n *\n"
    " * Each key is [label, shifted label, HI"
    "D usage].  The HID goes out beside the\n "
    "* character because this system's keycod"
    "es are USB usage ids and applications\n *"
    " read either - a shell wants the charact"
    "er, DOOM wants the key.\n */\nconst KEYS ="
    " [\n  [[\"1\",\"!\",K[\"1\"]],[\"2\",\"@\",K[\"2\"]],"
    "[\"3\",\"#\",K[\"3\"]],[\"4\",\"$\",K[\"4\"]],\n   [\""
    "5\",\"%\",K[\"5\"]],[\"6\",\"^\",K[\"6\"]],[\"7\",\"&\""
    ",K[\"7\"]],[\"8\",\"*\",K[\"8\"]],\n   [\"9\",\"(\",K"
    "[\"9\"]],[\"0\",\")\",K[\"0\"]]],\n  [[\"q\",\"Q\",K."
    "q],[\"w\",\"W\",K.w],[\"e\",\"E\",K.e],[\"r\",\"R\","
    "K.r],[\"t\",\"T\",K.t],\n   [\"y\",\"Y\",K.y],[\"u"
    "\",\"U\",K.u],[\"i\",\"I\",K.i],[\"o\",\"O\",K.o],["
    "\"p\",\"P\",K.p]],\n  [[\"a\",\"A\",K.a],[\"s\",\"S\""
    ",K.s],[\"d\",\"D\",K.d],[\"f\",\"F\",K.f],[\"g\",\""
    "G\",K.g],\n   [\"h\",\"H\",K.h],[\"j\",\"J\",K.j],"
    "[\"k\",\"K\",K.k],[\"l\",\"L\",K.l]],\n  [[\"z\",\"Z"
    "\",K.z],[\"x\",\"X\",K.x],[\"c\",\"C\",K.c],[\"v\","
    "\"V\",K.v],[\"b\",\"B\",K.b],\n   [\"n\",\"N\",K.n]"
    ",[\"m\",\"M\",K.m],\n   [\",\",\"<\",K.comma],[\"."
    "\",\">\",K.period]],\n  [[\"\\\\\",\"|\",K.backsla"
    "sh],[\";\",\":\",K.semicolon],[\"-\",\"_\",K.min"
    "us],\n   [\"/\",\"?\",K.slash],[\"=\",\"+\",K.equ"
    "al],[\"'\",\"\\\"\",K.quote],\n   [\"[\",\"{\",K.lb"
    "racket],[\"]\",\"}\",K.rbracket]],\n];\n\nlet s"
    "hifted = false;\n\nfunction keyButton(spec"
    ") {\n  const b = document.createElement(\""
    "button\");\n  const paint = () => { b.text"
    "Content = shifted ? spec[1] : spec[0]; }"
    ";\n  paint();\n  b._paint = paint;\n  b.add"
    "EventListener(\"pointerdown\", (e) => {\n  "
    "  e.preventDefault();\n    const ch = shi"
    "fted ? spec[1] : spec[0];\n    const mods"
    " = st.sticky | (shifted ? MOD.shift : 0)"
    ";\n    /*\n     * With Ctrl or Alt armed t"
    "his is a chord and not a character: the "
    "shell\n     * wants Ctrl+C as a keystroke"
    " with a keycode, not as the letter c.\n  "
    "   */\n    const uni = (st.sticky & (MOD."
    "ctrl | MOD.alt)) ? 0 : ch.codePointAt(0)"
    ";\n    sendKey(1, spec[2], uni, mods);\n  "
    "  sendKey(2, spec[2], 0, mods);\n    clea"
    "rSticky();\n    if (shifted) { shifted = "
    "false; repaintKeys(); }\n  });\n  return b"
    ";\n}\n\nfunction specialButton(label, cls, "
    "fn) {\n  const b = document.createElement"
    "(\"button\");\n  b.textContent = label;\n  i"
    "f (cls) b.className = cls;\n  b.addEventL"
    "istener(\"pointerdown\", (e) => { e.preven"
    "tDefault(); fn(b); });\n  return b;\n}\n\nfu"
    "nction repaintKeys() {\n  for (const b of"
    " ui.kbd.querySelectorAll(\"button\")) {\n  "
    "  if (b._paint) b._paint();\n  }\n  const "
    "sh = ui.kbd.querySelector(\"button.shift\""
    ");\n  if (sh) sh.classList.toggle(\"held\","
    " shifted);\n}\n\nfunction buildKeyboard() {"
    "\n  for (let i = 0; i < KEYS.length; i++)"
    " {\n    const row = document.createElemen"
    "t(\"div\");\n    row.className = \"row\";\n   "
    " if (i === 3) {\n      const sh = special"
    "Button(\"\342\207\247\", \"mod shift\", () => {\n     "
    "   shifted = !shifted;\n        repaintKe"
    "ys();\n      });\n      sh.classList.add(\""
    "shift\");\n      row.appendChild(sh);\n    "
    "}\n    for (const spec of KEYS[i]) row.ap"
    "pendChild(keyButton(spec));\n    if (i =="
    "= 2) {\n      row.appendChild(specialButt"
    "on(\"\342\214\253\", \"mod\", () => tap(K.back)));\n  "
    "  }\n    if (i === 3) {\n      row.appendC"
    "hild(specialButton(\"\342\217\216\", \"mod\", () => t"
    "ap(K.enter)));\n    }\n    ui.kbd.appendCh"
    "ild(row);\n  }\n\n  const last = document.c"
    "reateElement(\"div\");\n  last.className = "
    "\"row\";\n  last.appendChild(specialButton("
    "\"Esc\", \"mod\", () => tap(K.esc)));\n  last"
    ".appendChild(specialButton(\"Tab\", \"mod\","
    " () => tap(K.tab)));\n  /* Space carries "
    "its character as well as its usage id.  "
    "The kernel maps a\n   * usage to a charac"
    "ter for a real USB keyboard, so this wou"
    "ld work either\n   * way - but a key that"
    " means a character and does not say so i"
    "s a key that\n   * depends on somebody el"
    "se's table staying right. */\n  last.appe"
    "ndChild(specialButton(\"space\", \"xwide\", "
    "() => {\n    sendKey(1, K.space, 32, st.s"
    "ticky);\n    sendKey(2, K.space, 0, st.st"
    "icky);\n    clearSticky();\n  }));\n  last."
    "appendChild(specialButton(\"`\", \"mod\", ()"
    " => {\n    sendKey(1, K.grave, shifted ? "
    "126 : 96, st.sticky);\n    sendKey(2, K.g"
    "rave, 0, st.sticky);\n    clearSticky();\n"
    "  }));\n  last.appendChild(specialButton("
    "\"\342\214\253\", \"mod\", () => tap(K.back)));\n  ui."
    "kbd.appendChild(last);\n}\n\nbuildKeyboard("
    ");\n\n/*\n * Up by default on anything with"
    " a finger, folded away on a desktop wher"
    "e a\n * real keyboard is already attached"
    " and these keys are only lost screen.  A"
    "\n * phone that opens this page and sees "
    "no keys has, from where its owner is\n * "
    "standing, no keyboard at all - which is "
    "exactly how the first version was\n * rep"
    "orted.\n */\nif (window.matchMedia && wind"
    "ow.matchMedia(\"(pointer: coarse)\").match"
    "es) {\n  ui.kbd.classList.add(\"on\");\n  ui"
    ".kb.classList.add(\"held\");\n}\n\nui.kb.oncl"
    "ick = () => {\n  ui.kbd.classList.toggle("
    "\"on\");\n  ui.kb.classList.toggle(\"held\", "
    "ui.kbd.classList.contains(\"on\"));\n};\n\n/*"
    " The phone's own, for whoever wants it. "
    " It may or may not appear - that is\n * t"
    "he browser's decision and the reason the"
    " keys above exist. */\nui.native.onclick "
    "= () => {\n  ui.sink.value = \"\";\n  ui.sin"
    "k.focus();\n};\n\n/*\n * A phone's keyboard "
    "reports characters, not keys.  Two paths"
    ", and both are\n * needed: `keydown` carr"
    "ies the named keys on anything with a re"
    "al keyboard and\n * often nothing useful "
    "on a touch one, while the hidden textare"
    "a's `input`\n * event carries what was ac"
    "tually composed - including anything pas"
    "t ASCII,\n * which has no HID usage to be"
    " named by.\n */\nconst BY_CODE = {\n  Escap"
    "e: K.esc, Tab: K.tab, Enter: K.enter, Ba"
    "ckspace: K.back,\n  ArrowUp: K.up, ArrowD"
    "own: K.down, ArrowLeft: K.left, ArrowRig"
    "ht: K.right,\n  Home: K.home, End: K.end,"
    " PageUp: K.pgup, PageDown: K.pgdn, Delet"
    "e: K.del,\n  Space: K.space,\n};\nfor (let "
    "i = 1; i <= 12; i++) BY_CODE[\"F\" + i] = "
    "K[\"f\" + i];\n\nwindow.addEventListener(\"ke"
    "ydown\", (e) => {\n  let mods = 0;\n  if (e"
    ".shiftKey) mods |= MOD.shift;\n  if (e.ct"
    "rlKey) mods |= MOD.ctrl;\n  if (e.altKey)"
    " mods |= MOD.alt;\n  if (e.metaKey) mods "
    "|= MOD.gui;\n  mods |= st.sticky;\n\n  let "
    "hid = BY_CODE[e.code] || 0;\n  if (!hid &"
    "& /^Key[A-Z]$/.test(e.code)) hid = K[e.c"
    "ode[3].toLowerCase()];\n  if (!hid && /^D"
    "igit[0-9]$/.test(e.code)) hid = K[e.code"
    "[5]];\n\n  const uni = (e.key && e.key.len"
    "gth === 1) ? e.key.codePointAt(0) : 0;\n "
    " if (!hid && !uni) return;\n\n  e.preventD"
    "efault();\n  sendKey(1, hid, (mods & MOD."
    "ctrl) ? 0 : uni, mods);\n  sendKey(2, hid"
    ", 0, mods);\n  clearSticky();\n});\n\nui.sin"
    "k.addEventListener(\"input\", () => {\n  co"
    "nst text = ui.sink.value;\n  ui.sink.valu"
    "e = \"\";\n  if (!text) return;\n  /*\n   * W"
    "ith Ctrl or Alt armed this is not text, "
    "it is a chord: the shell wants\n   * Ctrl"
    "+C as a keystroke with a keycode, not as"
    " the letter c.\n   */\n  if (st.sticky && "
    "text.length === 1) {\n    const c = text."
    "toLowerCase();\n    const hid = K[c] || 0"
    ";\n    if (hid) { tap(hid); return; }\n  }"
    "\n  send([IN_TEXT, ...new TextEncoder().e"
    "ncode(text)]);\n  clearSticky();\n});\n\nui."
    "sink.addEventListener(\"beforeinput\", (e)"
    " => {\n  if (e.inputType === \"deleteConte"
    "ntBackward\") { e.preventDefault(); tap(K"
    ".back); }\n  if (e.inputType === \"insertL"
    "ineBreak\") { e.preventDefault(); tap(K.e"
    "nter); }\n});\n\n/* ---- the pointer ------"
    "----------------------------------------"
    "-------- */\n\n/*\n * Where a touch lands, "
    "in the pixels the board measures a point"
    "er in.\n *\n * Two different surfaces and "
    "the board says which is live: an applica"
    "tion's,\n * whose size arrived with the p"
    "icture, and the console's, which has no "
    "pixels\n * of its own and is measured in "
    "cells times the cell size the kernel dra"
    "ws\n * with.  Getting this wrong is the b"
    "ug that put the cursor below the stylus "
    "on\n * the board's own touchscreen for a "
    "week, so it is computed from what the bo"
    "ard\n * said rather than from what looks "
    "right.\n */\nfunction where(ev) {\n  const "
    "cv = (st.mode === \"pix\") ? ui.pix : ui.t"
    "ext;\n  const r = cv.getBoundingClientRec"
    "t();\n  if (r.width === 0 || r.height ==="
    " 0) return null;\n\n  const fx = (ev.clien"
    "tX - r.left) / r.width;\n  const fy = (ev"
    ".clientY - r.top) / r.height;\n  if (fx <"
    " 0 || fx > 1 || fy < 0 || fy > 1) return"
    " null;\n\n  if (st.mode === \"pix\") {\n    r"
    "eturn [Math.floor(fx * st.surfW), Math.f"
    "loor(fy * st.surfH)];\n  }\n  const col = "
    "Math.min(st.cols - 1, Math.floor(fx * st"
    ".cols));\n  const row = Math.min(st.rows "
    "- 1, Math.floor(fy * st.rows));\n  return"
    " [col * st.cellW, row * st.cellH];\n}\n\nfu"
    "nction sendPtr(kind, ev, buttons) {\n  co"
    "nst p = where(ev);\n  if (!p) return;\n  s"
    "end([IN_PTR, kind, buttons, p[0] & 255, "
    "(p[0] >> 8) & 255,\n        p[1] & 255, ("
    "p[1] >> 8) & 255, 0]);\n}\n\nfor (const cv "
    "of [ui.text, ui.pix]) {\n  cv.addEventLis"
    "tener(\"pointerdown\", (e) => {\n    e.prev"
    "entDefault();\n    cv.setPointerCapture(e"
    ".pointerId);\n    st.ptrDown = true;\n    "
    "sendPtr(1, e, 1);\n  });\n  cv.addEventLis"
    "tener(\"pointermove\", (e) => {\n    if (!s"
    "t.ptrDown) return;\n    e.preventDefault("
    ");\n    sendPtr(3, e, 1);\n  });\n  cv.addE"
    "ventListener(\"pointerup\", (e) => {\n    i"
    "f (!st.ptrDown) return;\n    e.preventDef"
    "ault();\n    st.ptrDown = false;\n    send"
    "Ptr(2, e, 0);\n  });\n  cv.addEventListene"
    "r(\"pointercancel\", () => { st.ptrDown = "
    "false; });\n  cv.addEventListener(\"contex"
    "tmenu\", (e) => e.preventDefault());\n}\n\n/"
    "*\n * Coming back from a locked screen.  "
    "The socket is usually dead by then and t"
    "he\n * browser has not noticed, so ask fo"
    "r everything: the board answers 'H' by\n "
    "* resending the geometry and marking the"
    " whole screen as owed.\n */\ndocument.addE"
    "ventListener(\"visibilitychange\", () => {"
    "\n  if (document.visibilityState !== \"vis"
    "ible\") return;\n  if (!st.ws || st.ws.rea"
    "dyState !== 1) { connect(); return; }\n  "
    "send([IN_HELLO]);\n});\n\nresizeText();\ncon"
    "nect();\n</script>\n";

#endif /* AG_PHONE_PAGE_H */
